64	// 题目示例：查看 3 月 9 日至 3 月 11 日应得到旧版和新版；
65	// 查看 3 月 10 日至 3 月 25 日只得到新版；查看 3 月 20 日至 3 月 25 日为空。
66	func TestVersionsInRangeSpecExample(t *testing.T) {
67		b := newRangeBook(t)
68	
69		got, err := b.VersionsInRange("seat",
70			time.Date(2026, 3, 9, 0, 0, 0, 0, time.UTC),
71			time.Date(2026, 3, 11, 0, 0, 0, 0, time.UTC))
72		if err != nil {
73			t.Fatalf("3 月 9 日至 11 日不应报错: %v", err)
74		}
75		if ids := rangeIDs(got); !equalIDs(ids, "seat-v1", "seat-v2") {
76			t.Fatalf("3 月 9 日至 11 日应依次得到旧版和新版, got %v", ids)
77		}
78	
79		got, err = b.VersionsInRange("seat", rngV2Start,
80			time.Date(2026, 3, 25, 0, 0, 0, 0, time.UTC))
81		if err != nil {
82			t.Fatalf("3 月 10 日至 25 日不应报错: %v", err)
83		}
84		if ids := rangeIDs(got); !equalIDs(ids, "seat-v2") {
85			t.Fatalf("3 月 10 日至 25 日应只得到新版, got %v", ids)
86		}
