241	// 范围合法但费率项从未登记过版本时，沿用现有的费率项未找到错误；
242	// 费率项存在但范围内没有命中版本时，返回空列表且不报错。
243	func TestVersionsInRangeMissingItemVsEmptyResult(t *testing.T) {
