268	// 空档不补入相邻版本：范围覆盖两段版本之间的空档时，只列出实际相交的版本。
269	func TestVersionsInRangeGapNotFilled(t *testing.T) {
270		b := NewBook()
271		must := func(r RegisterRequest) {
272			t.Helper()
273			if err := b.RegisterVersion(r); err != nil {
274				t.Fatalf("register %+v: %v", r, err)
275			}
276		}
277		// 两段不涉及替代的区间，中间留 3 月 10 日至 3 月 20 日的空档。
278		must(RegisterRequest{
279			ItemID: "gap", VersionID: "g1", UnitPrice: 100,
280			Start: time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC),
281			End:   ptrTime(time.Date(2026, 3, 10, 0, 0, 0, 0, time.UTC)),
282		})
