289		// 范围跨过整个空档：两段都命中，空档本身不产生任何版本。
290		got, err := b.VersionsInRange("gap",
291			time.Date(2026, 3, 5, 0, 0, 0, 0, time.UTC),
292			time.Date(2026, 3, 25, 0, 0, 0, 0, time.UTC))
293		if err != nil {
