312	// 返回列表沿用现有版本视图：保留登记起止、实际有效区间和替代关系，
313	// 不把版本边界改成查询范围的边界；按实际生效起点从早到晚排列，每版只出现一次。
314	func TestVersionsInRangeViewFieldsAndOrdering(t *testing.T) {
315		b := newRangeBook(t)
316	
317		got, err := b.VersionsInRange("seat",
318			time.Date(2026, 3, 9, 0, 0, 0, 0, time.UTC),
319			time.Date(2026, 3, 11, 0, 0, 0, 0, time.UTC))
320		if err != nil {
321			t.Fatal(err)
322		}
323		if len(got) != 2 {
324			t.Fatalf("应命中两版, got %v", rangeIDs(got))
325		}
326	
327		old, nv := got[0], got[1]
328		if old.VersionID != "seat-v1" || nv.VersionID != "seat-v2" {
329			t.Fatalf("应按实际生效起点从早到晚排列: %v", rangeIDs(got))
330		}
331	
332		// 旧版保留登记边界与截短后的实际边界，不被查询范围 [3-09, 3-11) 改写。
333		if old.ItemID != "seat" || old.UnitPrice != 150 {
334			t.Fatalf("旧版标识/单价异常: %+v", old)
335		}
336		if !old.Start.Equal(rngV1Start) || !old.EffectiveStart.Equal(rngV1Start) {
337			t.Fatalf("旧版开始边界不应被改成范围开始: %+v", old)
338		}
339		if old.End == nil || !old.End.Equal(rngV1End) {
340			t.Fatalf("旧版应保留登记结束 3 月 31 日: %v", old.End)
341		}
342		if old.EffectiveEnd == nil || !old.EffectiveEnd.Equal(rngV2Start) {
343			t.Fatalf("旧版实际结束应显示交接点 3 月 10 日: %v", old.EffectiveEnd)
344		}
345		if old.Replaces != "" || old.SupersededBy != "seat-v2" {
346			t.Fatalf("旧版替代关系异常: Replaces=%q SupersededBy=%q", old.Replaces, old.SupersededBy)
347		}
348	
349		if nv.UnitPrice != 180 || !nv.Start.Equal(rngV2Start) || !nv.EffectiveStart.Equal(rngV2Start) {
350			t.Fatalf("新版视图异常: %+v", nv)
351		}
352		if nv.End == nil || !nv.End.Equal(rngV2End) || nv.EffectiveEnd == nil || !nv.EffectiveEnd.Equal(rngV2End) {
353			t.Fatalf("新版结束边界不应被改成范围结束: %+v", nv)
354		}
355		if nv.Replaces != "seat-v1" || nv.SupersededBy != "" {
356			t.Fatalf("新版替代关系异常: Replaces=%q SupersededBy=%q", nv.Replaces, nv.SupersededBy)
357		}
358	
359		// 无论范围与版本相交多少次，每个版本只出现一次：大范围包含两版完整区间。
360		got, err = b.VersionsInRange("seat",
361			time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC),
362			time.Date(2027, 1, 1, 0, 0, 0, 0, time.UTC))
363		if err != nil {
364			t.Fatal(err)
365		}
366		if ids := rangeIDs(got); !equalIDs(ids, "seat-v1", "seat-v2") {
367			t.Fatalf("大范围应各列一次、按起点排序: %v", ids)
368		}
369	}
