393	// 选择只在指定费率项内进行：其他费率项即使有同名版本也不参与。
394	func TestVersionsInRangeScopedToItem(t *testing.T) {
395		b := NewBook()
396		must := func(r RegisterRequest) {
397			t.Helper()
398			if err := b.RegisterVersion(r); err != nil {
399				t.Fatalf("register %+v: %v", r, err)
400			}
401		}
