469	// 选择依据是查询时账本已登记的版本：补登过去生效的替代版本后，
470	// 同一历史范围的回答按当前登记的实际区间变化。
471	func TestVersionsInRangeReflectsRetroactiveRegistration(t *testing.T) {
472		b := NewBook()
