507	// 查询是只读操作：不受理报价、不占用请求标识；
508	// 返回视图是独立副本，改写其中的结束时间不影响后续查询和报价。
509	func TestVersionsInRangeReadOnlyAndIsolated(t *testing.T) {
510		b, setNow := newEffectiveVersionBook(t, effV1Start)
511	
512		got, err := b.VersionsInRange("seat",
513			time.Date(2026, 3, 9, 0, 0, 0, 0, time.UTC),
514			time.Date(2026, 3, 11, 0, 0, 0, 0, time.UTC))
515		if err != nil {
516			t.Fatal(err)
517		}
518		if len(got) != 2 {
519			t.Fatalf("前提：应命中两版, got %v", rangeIDs(got))
520		}
521	
522		// 调用方改写返回视图中的结束时间。
523		*got[0].End = time.Date(2099, 1, 1, 0, 0, 0, 0, time.UTC)
524		*got[0].EffectiveEnd = time.Date(2099, 1, 1, 0, 0, 0, 0, time.UTC)
525		*got[1].End = time.Date(2099, 1, 1, 0, 0, 0, 0, time.UTC)
526		*got[1].EffectiveEnd = time.Date(2099, 1, 1, 0, 0, 0, 0, time.UTC)
527	
528		// 再次范围查询：边界仍是账本原值，且与上次返回不共享指针。
529		again, err := b.VersionsInRange("seat",
530			time.Date(2026, 3, 9, 0, 0, 0, 0, time.UTC),
531			time.Date(2026, 3, 11, 0, 0, 0, 0, time.UTC))
532		if err != nil {
533			t.Fatal(err)
534		}
535		if again[0].End == nil || !again[0].End.Equal(effV1End) {
536			t.Fatalf("登记结束被查询结果的修改改写: %v", again[0].End)
537		}
538		if again[0].EffectiveEnd == nil || !again[0].EffectiveEnd.Equal(effV2Start) {
539			t.Fatalf("实际结束被查询结果的修改改写: %v", again[0].EffectiveEnd)
540		}
541		if got[0].End == again[0].End || got[0].EffectiveEnd == again[0].EffectiveEnd {
542			t.Fatal("两次范围查询共享了结束时间指针")
543		}
544	
545		// 其他查询入口同样未被污染。
546		view, err := b.EffectiveVersionAt("seat", time.Date(2026, 3, 5, 0, 0, 0, 0, time.UTC))
547		if err != nil || view.EffectiveEnd == nil || !view.EffectiveEnd.Equal(effV2Start) {
548			t.Fatalf("EffectiveVersionAt 被范围查询结果的修改污染: %+v (%v)", view, err)
549		}
550	
551		// 报价仍按账本真实区间处理：交接点起旧版失效、新版有效。
552		setNow(effV2Start)
553		out, _ := b.Quote(QuoteRequest{RequestID: "q-old", ItemID: "seat", VersionID: "seat-v1", Quantity: 1})
554		if out.Confirmed || out.Reason != ReasonVersionExpired {
555			t.Fatalf("修改范围查询结果不能影响后续报价依据: %+v", out)
556		}
557		out, _ = b.Quote(QuoteRequest{RequestID: "q-new", ItemID: "seat", VersionID: "seat-v2", Quantity: 1})
558		if !out.Confirmed {
559			t.Fatalf("新版在交接点应可报价: %+v", out)
560		}
561	
562		// 范围查询本身不产生任何报价记录、不占用请求标识。
563		if _, err := b.Lookup("range-query-check"); !errors.Is(err, ErrRequestNotFound) {
564			t.Fatalf("只读查询不应产生报价记录: %v", err)
565		}
566		fresh, err := b.Quote(QuoteRequest{RequestID: "range-query-check", ItemID: "seat", VersionID: "seat-v2", Quantity: 2})
567		if err != nil || !fresh.Confirmed || fresh.Total != 360 {
568			t.Fatalf("范围查询不应占用请求标识或影响首次受理: %+v (%v)", fresh, err)
569		}
570	}
571	
572	// 并发只读范围查询应始终给出一致结论。
573	func TestVersionsInRangeConcurrentReads(t *testing.T) {
574		b := newRangeBook(t)
575	
576		const n = 32
577		var wg sync.WaitGroup
578		errs := make(chan error, n)
579		for i := 0; i < n; i++ {
580			wg.Add(1)
581			go func(i int) {
582				defer wg.Done()
583				got, err := b.VersionsInRange("seat",
584					time.Date(2026, 3, 9, 0, 0, 0, 0, time.UTC),
585					time.Date(2026, 3, 11, 0, 0, 0, 0, time.UTC))
586				if err != nil {
587					errs <- fmt.Errorf("查询 %d: %w", i, err)
588					return
589				}
590				if ids := rangeIDs(got); !equalIDs(ids, "seat-v1", "seat-v2") {
591					errs <- fmt.Errorf("查询 %d 结果异常: %v", i, ids)
592				}
593			}(i)
594		}
595		wg.Wait()
596		close(errs)
597		for err := range errs {
598			t.Error(err)
599		}
600	}
